def page_items(items, count):
    if count < 0:
        return []
    return items[:count]

print(page_items(["A", "B", "C"], 2))

8.starterCode:
def rotate_turns(players, cut):
    return players[cut:] + players[:cut]

print(rotate_turns(["A", "B", "C", "D"], 2))

9.starterCode:
def round_window(rounds, start, stop):
    return rounds[start:stop]

print(round_window([10, 20, 30, 40, 50], 1, 4))

10.starterCode:
def recent_window(items, count):
    if count < 1:
        return []
    return items[-count:]

print(recent_window([1, 2, 3, 4], 2))
